CREATE TABLE IF NOT EXISTS `squads` (`id` INT AUTO_INCREMENT PRIMARY KEY, `name` VARCHAR(40) NOT NULL, `code` VARCHAR(8) NOT NULL UNIQUE, `created_by` INT NOT NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT `fk_squads_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `squad_members` (`squad_id` INT NOT NULL, `user_id` INT NOT NULL UNIQUE, `joined_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`squad_id`, `user_id`), CONSTRAINT `fk_squad_members_squad` FOREIGN KEY (`squad_id`) REFERENCES `squads` (`id`) ON DELETE CASCADE, CONSTRAINT `fk_squad_members_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
